const requests = [
  { ok: true, ms: 80 },
  { ok: true, ms: 90 },
  { ok: false, ms: 500 },
  { ok: true, ms: 110 },
  { ok: true, ms: 120 }
];
const failures = requests.filter(item => !item.ok).length;
const successful = requests.filter(item => item.ok);
const totalMs = successful.reduce((sum, item) => sum + item.ms, 0);
console.log("requests: " + requests.length);
console.log("failures: " + failures);
console.log("error percent: " + failures / requests.length * 100);
console.log("successful average ms: " + totalMs / successful.length);
